sed -i '' 's/<script>/<script>\nwindow.onerror = function(msg, url, line, col, error) { const errEl = document.createElement("div"); errEl.style="color:red;padding:10px;"; errEl.innerText = "Error: " + msg + " at " + line + ":" + col; document.body.prepend(errEl); };\nwindow.addEventListener("unhandledrejection", function(e) { const errEl = document.createElement("div"); errEl.style="color:red;padding:10px;"; errEl.innerText = "Unhandled promise rejection: " + (e.reason && e.reason.message ? e.reason.message : e.reason); document.body.prepend(errEl); });/' waypost/ui.py
